"""CSV / Parquet readers and writers."""
from __future__ import annotations

import os

import numpy as np
import pandas as pd


def _fmt(path: str) -> str:
    p = path.lower()
    for ext in (".gz", ".zst", ".bz2"):
        if p.endswith(ext):
            p = p[: -len(ext)]
    if p.endswith((".parquet", ".pq")):
        return "parquet"
    if p.endswith(".tsv"):
        return "tsv"
    if p.endswith(".csv"):
        return "csv"
    raise ValueError(f"unsupported file type: {path} (use .csv/.tsv/.parquet)")


def read_table(path: str, parse_dates: list[str] | None = None) -> pd.DataFrame:
    fmt = _fmt(path)
    if fmt == "parquet":
        try:
            return pd.read_parquet(path)
        except ImportError as e:
            raise SystemExit("Parquet needs pyarrow: pip install 'provenmark[parquet]'") from e
    sep = "\t" if fmt == "tsv" else ","
    df = pd.read_csv(path, sep=sep)
    _exact_floats(df, pd.read_csv(path, sep=sep, dtype=str, keep_default_na=False, na_filter=False))
    for c in parse_dates or []:
        if c in df.columns and not pd.api.types.is_numeric_dtype(df[c]):
            df[c] = pd.to_datetime(df[c], utc=True, format="mixed")
    return df


def _exact_floats(df: pd.DataFrame, raw: pd.DataFrame) -> None:
    """Re-parse every float column from its text with Python's correctly rounded float(), in place.
    Fingerprints and detection statistics must not depend on the CSV parser: pandas' default C parser is off by a few
    ulps for ~1 in 6 values written with 17 significant digits, and `float_precision="round_trip"` (which uses the
    same correctly rounded parser) is deprecated. Type inference and missing values are left to pandas."""
    for j, c in enumerate(df.columns):
        if not pd.api.types.is_float_dtype(df[c]):
            continue
        x = df.iloc[:, j].to_numpy(dtype=np.float64, copy=True)
        ok = ~np.isnan(x)
        txt = raw.iloc[:, j].to_numpy()
        x[ok] = [float(v) for v in txt[ok]]
        df.isetitem(j, pd.Series(x, index=df.index, name=c).astype(df[c].dtype))


def write_table(df: pd.DataFrame, path: str) -> None:
    fmt = _fmt(path)
    if fmt == "parquet":
        try:
            df.to_parquet(path, index=False)
        except ImportError as e:
            raise SystemExit("Parquet needs pyarrow: pip install 'provenmark[parquet]'") from e
    else:
        df.to_csv(path, index=False, sep="\t" if fmt == "tsv" else ",")


def default_out(path: str, suffix: str) -> str:
    base, ext = os.path.splitext(path)
    return f"{base}{suffix}{ext}"
